/**
 * Helpers for the built-in terrain tile pack (`public/backgrounds/`).
 * Pure functions only, so the map layer, the picker, and the tests all
 * share one notion of where a tile lives.
 *
 * Manifest shape lives in `public/backgrounds/index.json` (generated by
 * `scripts/build-backgrounds.mjs` from `sources.json`).
 */

const URL_PATTERN = /(?:^|\/)backgrounds\/tiles\/[^/]+\.webp$/;

function resolveBase(base) {
  if (typeof base !== 'string') return '/';
  if (base === '') return '/';
  if (!base.endsWith('/')) return base + '/';
  return base;
}

function getEnvBase() {
  try {
    if (typeof import.meta !== 'undefined' && import.meta.env?.BASE_URL) {
      return import.meta.env.BASE_URL;
    }
  } catch {
    // import.meta unavailable in some test contexts
  }
  return '/';
}

/** Static URL for a tile. `id` is the manifest slug, no extension. */
export function builtinTileUrl(id, base) {
  return `${resolveBase(base ?? getEnvBase())}backgrounds/tiles/${id}.webp`;
}

/** Does this URL point at our own tile pack, needing no mxc resolution? */
export function isBuiltinTileUrl(url) {
  if (typeof url !== 'string' || url === '') return false;
  if (url.startsWith('mxc://') || /^[a-z]+:\/\//i.test(url)) return false;
  return URL_PATTERN.test(url);
}

let _manifestPromise = null;
let _manifestCache = null;

/**
 * Fetch and memoise the tile manifest. First call kicks off the
 * request; subsequent calls return the same promise / cached value.
 */
export function loadBackgroundManifest(base) {
  if (_manifestCache) return Promise.resolve(_manifestCache);
  if (_manifestPromise) return _manifestPromise;
  const b = resolveBase(base ?? getEnvBase());
  _manifestPromise = fetch(`${b}backgrounds/index.json`)
    .then((r) => {
      if (!r.ok) throw new Error(`tile manifest fetch failed: ${r.status}`);
      return r.json();
    })
    .then((m) => {
      _manifestCache = m;
      _manifestPromise = null;
      return m;
    })
    .catch((err) => {
      _manifestPromise = null;
      throw err;
    });
  return _manifestPromise;
}

// Test-only reset
export function _resetBackgroundManifestCache() {
  _manifestPromise = null;
  _manifestCache = null;
}
